package com.leetcode.backend.controller;
import com.leetcode.backend.dto.*; import com.leetcode.backend.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/assistant") public class AdminAssistantController { private final AdminAssistantService service; private final AssistantRateLimiter limiter; public AdminAssistantController(AdminAssistantService s,AssistantRateLimiter l){service=s;limiter=l;} @PostMapping("/chat") public AssistantChatResponse chat(@Valid @RequestBody AssistantChatRequest request,Authentication authentication){if(!limiter.allowed("admin:"+authentication.getName(),12))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Please wait a moment before sending another assistant message.");return service.chat(request);} }
